    checkProjectDependencies = async (projectId) => {
        try {
            const d2 = await getInstance();
            const api = d2.Api.getApi();

            let eventCount = 0;
            let enrollmentCount = 0;

            try {
                // Check for events
                const eventsResponse = await api.get('tracker/events', {
                    program: projectId,
                    pageSize: 1,
                    fields: 'event',
                    totalPages: true
                });
                eventCount = eventsResponse.pager ? eventsResponse.pager.total : 0;
            } catch (e) {
                // If tracker endpoint fails, try older events endpoint
                try {
                    const eventsResponse = await api.get(`programStageInstances.json`, {
                        program: projectId,
                        pageSize: 1,
                        totalPages: true
                    });
                    eventCount = eventsResponse.pager ? eventsResponse.pager.total : 0;
                } catch (e2) {
                    console.warn('Could not check events:', e2);
                }
            }

            // Check for enrollments
            try {
                const enrollmentsResponse = await api.get('tracker/enrollments', {
                    program: projectId,
                    pageSize: 1,
                    fields: 'enrollment',
                    totalPages: true
                });
                enrollmentCount = enrollmentsResponse.pager ? enrollmentsResponse.pager.total : 0;
            } catch (e) {
                // If tracker endpoint fails, try the older enrollments endpoint
                try {
                    const enrollmentsResponse = await api.get(`programInstances.json`, {
                        program: projectId,
                        pageSize: 1,
                        totalPages: true
                    });
                    enrollmentCount = enrollmentsResponse.pager ? enrollmentsResponse.pager.total : 0;
                } catch (e2) {
                    console.warn('Could not check enrollments:', e2);
                }
            }

            return {
                hasData: eventCount > 0 || enrollmentCount > 0,
                eventCount,
                enrollmentCount
            };
        } catch (error) {
            console.warn('Could not check dependencies:', error);
            return { hasData: false, eventCount: 0, enrollmentCount: 0 };
        }
    };

