    deleteAllProjectEvents = async (projectId) => {
        const d2 = await getInstance();
        const api = d2.Api.getApi();

        let deletedCount = 0;

        try {
            // Try to get events using multiple endpoints
            let eventIds = [];

            // Try tracker/events endpoint
            try {
                const eventsResponse = await api.get('tracker/events', {
                    program: projectId,
                    fields: 'event',
                    paging: false
                });

                if (eventsResponse.events && eventsResponse.events.length > 0) {
                    eventIds = eventsResponse.events.map(event => event.event);
                }
            } catch (e) {
                console.warn('tracker/events failed, trying programStageInstances:', e);

                // Try programStageInstances endpoint
                try {
                    const response = await api.get('programStageInstances', {
                        program: projectId,
                        fields: 'programStageInstance',
                        paging: false
                    });

                    if (response.programStageInstances && response.programStageInstances.length > 0) {
                        eventIds = response.programStageInstances.map(psi => psi.programStageInstance);
                    }
                } catch (e2) {
                    console.warn('programStageInstances also failed:', e2);
                }
            }

            if (eventIds.length > 0) {
                // Delete events in batches using tracker import API
                for (let i = 0; i < eventIds.length; i += 50) {
                    const batch = eventIds.slice(i, i + 50);

                    try {
                        const payload = {
                            events: batch.map(eventId => ({ event: eventId }))
                        };

                        const importResponse = await api.post('tracker?async=false&importStrategy=DELETE', payload);

                        if (importResponse.bundleReport && importResponse.bundleReport.stats) {
                            const batchDeletedCount = importResponse.bundleReport.stats.deleted || 0;
                            deletedCount += batchDeletedCount;
                        } else {
                            // Assume all were deleted if no specific count
                            deletedCount += batch.length;
                        }

                    } catch (batchError) {
                        console.warn(`Failed to delete batch of events:`, batchError);

                        // Fallback: try individual deletion for this batch
                        for (const eventId of batch) {
                            try {
                                await api.delete(`events/${eventId}`);
                                deletedCount++;
                            } catch (individualError) {
                                try {
                                    await api.delete(`programStageInstances/${eventId}`);
                                    deletedCount++;
                                } catch (psiError) {
                                    console.warn(`Failed to delete event ${eventId} individually:`, psiError);
                                }
                            }
                        }
                    }

                    // Small delay between batches
                    if (i + 50 < eventIds.length) {
                        await new Promise(resolve => setTimeout(resolve, 500));
                    }
                }
            }

        } catch (error) {
            console.error('Error deleting project events:', error);
        }

        return deletedCount;
    };

    forceDeleteProject = async (projectId, programId) => {
        // Show progress modal
        let progressModal = null;
        const updateProgress = (step, detail) => {
            if (progressModal) {
                progressModal.update({
                    content: (
                        <div>
                            <div style={{ textAlign: 'center', marginBottom: '16px' }}>
                                <Icon type="loading" style={{ fontSize: '32px', color: '#1890ff' }} />
                            </div>
                            <div style={{ marginBottom: '12px' }}>
                                <strong>Step {step} of 5:</strong> {detail}
                            </div>
                            <div style={{
                                height: '4px',
                                backgroundColor: '#f0f0f0',
                                borderRadius: '2px',
                                overflow: 'hidden'
                            }}>
                                <div style={{
                                    height: '100%',
                                    width: `${(step / 5) * 100}%`,
                                    backgroundColor: '#1890ff',
                                    transition: 'width 0.3s'
                                }} />
                            </div>
                        </div>
                    )
                });
            }
        };

        progressModal = Modal.info({
            title: 'Deleting Project with Dependencies',
            content: (
                <div>
                    <div style={{ textAlign: 'center', marginBottom: '16px' }}>
                        <Icon type="loading" style={{ fontSize: '32px', color: '#1890ff' }} />
                    </div>
                    <div>Starting cascade delete process...</div>
                </div>
            ),
            okButtonProps: { style: { display: 'none' } },
            closable: false,
            maskClosable: false,
        });

        this.setState({ deletingProjectId: projectId });

        try {
            const d2 = await getInstance();
            const api = d2.Api.getApi();

            // Step 1: Run initial maintenance to clean up any existing soft-deleted data
            updateProgress(1, 'Running initial maintenance cleanup...');
            const initialMaintenanceSuccess = await this.runMaintenanceCleanup();

            if (initialMaintenanceSuccess) {
                await new Promise(resolve => setTimeout(resolve, 3000)); // Wait longer
            } else {
                console.warn('Initial maintenance cleanup failed, but continuing...');
            }

            // Step 2: Delete all events in the project
            updateProgress(2, 'Deleting all associated events...');
            const deletedEventsCount = await this.deleteAllProjectEvents(projectId);

            // Step 3: Run maintenance again to permanently remove the deleted events
            updateProgress(3, 'Running maintenance to permanently remove deleted data...');
            const secondMaintenanceSuccess = await this.runMaintenanceCleanup();

            if (secondMaintenanceSuccess) {
                // Wait longer for maintenance to fully complete
                updateProgress(3, 'Waiting for maintenance to complete (this may take a few moments)...');
                await new Promise(resolve => setTimeout(resolve, 5000)); // Wait 5 seconds
            } else {
                console.warn('Second maintenance cleanup failed, but continuing with project deletion');
                await new Promise(resolve => setTimeout(resolve, 2000));
            }

            // Step 4: Attempt to delete the project
            updateProgress(4, 'Attempting to delete the project...');
            let deletionSucceeded = false;
            let lastError = null;
            let retryCount = 0;
            const maxRetries = 3;

            while (!deletionSucceeded && retryCount < maxRetries) {
                try {
                    if (retryCount > 0) {
                        updateProgress(4, `Retrying delete (attempt ${retryCount + 1} of ${maxRetries})...`);
                        // Wait between retries
                        await new Promise(resolve => setTimeout(resolve, 2000));
                    }

                    await api.delete(`programs/${projectId}`);
                    await new Promise(resolve => setTimeout(resolve, 1000));
                    deletionSucceeded = await this.verifyProjectDeleted(projectId);

                    if (deletionSucceeded) {
                        break;
                    } else {
                        throw new Error('Project deletion verification failed');
                    }
                } catch (deleteError) {
                    console.warn(`Delete attempt ${retryCount + 1} failed:`, deleteError);
                    lastError = deleteError;
                    retryCount++;

                    // If we've exhausted normal retries, try force delete
                    if (retryCount >= maxRetries) {
                        try {
                            updateProgress(4, 'Attempting force delete...');
                            await api.delete(`programs/${projectId}?force=true`);
                            await new Promise(resolve => setTimeout(resolve, 1000));
                            deletionSucceeded = await this.verifyProjectDeleted(projectId);
                        } catch (forceError) {
                            console.error('Force delete also failed:', forceError);
                            lastError = forceError;
                        }
                    }
                }
            }

            // Step 5: Finalize
            if (deletionSucceeded) {
                updateProgress(5, 'Project deleted successfully!');
                await new Promise(resolve => setTimeout(resolve, 500));

                // Remove the deleted project from state
                const updatedProjects = { ...this.state.projects };
                if (updatedProjects[programId]) {
                    updatedProjects[programId] = updatedProjects[programId].filter(project => project.id !== projectId);
                }

                this.setState({
                    projects: updatedProjects,
                    deletingProjectId: null
                });

                if (progressModal) {
                    progressModal.destroy();
                }

                message.success(`Project and ${deletedEventsCount} associated event(s) successfully deleted`);
            } else {
                throw lastError || new Error('Project deletion failed after all retry attempts');
            }
        } catch (error) {
            console.error('Error in force delete project:', error);
            this.setState({ deletingProjectId: null });

            if (progressModal) {
                progressModal.destroy();
            }

            // Provide more specific error messages
            let errorMessage = 'Failed to delete the project';
            let troubleshootingSteps = [];

            if (error.httpStatusCode === 409 ||
                (error.message && error.message.includes('associated with another object'))) {
                errorMessage = 'The project still has dependencies that could not be automatically removed.';
                troubleshootingSteps = [
                    'The project may have dependencies other than events (e.g., tracked entities, indicators, validation rules)',
                    'Try manually checking and removing these dependencies',
                    'Contact your system administrator to manually inspect the database',
                ];
            } else if (error.httpStatusCode === 403) {
                errorMessage = 'You do not have sufficient permissions to delete this project.';
                troubleshootingSteps = [
                    'Contact your system administrator to grant you delete permissions',
                ];
            } else {
                troubleshootingSteps = [
                    'Wait a few minutes and try again',
                    'Check if system maintenance tasks are running',
                    'Contact your system administrator for assistance',
                ];
            }

            Modal.error({
                title: 'Cascade Delete Failed',
                content: (
                    <div>
                        <p><strong>{errorMessage}</strong></p>
                        <div style={{ backgroundColor: '#fff7e6', border: '1px solid #ffd591', borderRadius: '4px', padding: '12px', margin: '12px 0' }}>
                            <p style={{ margin: '0 0 8px 0', fontWeight: 'bold', color: '#fa8c16' }}>
                                <Icon type="bulb" style={{ marginRight: '8px' }} />
                                Troubleshooting:
                            </p>
                            <ul style={{ margin: 0, paddingLeft: '16px', fontSize: '12px' }}>
                                {troubleshootingSteps.map((step, index) => (
                                    <li key={index}>{step}</li>
                                ))}
                            </ul>
                        </div>
                        <details style={{ marginTop: '12px' }}>
                            <summary style={{ cursor: 'pointer', fontSize: '12px', color: '#666' }}>
                                Technical Details
                            </summary>
                            <pre style={{ fontSize: '10px', overflow: 'auto', maxHeight: '100px', marginTop: '8px', backgroundColor: '#f5f5f5', padding: '8px', borderRadius: '4px' }}>
                                {JSON.stringify(error.response || error, null, 2)}
                            </pre>
                        </details>
                    </div>
                ),
                width: 650,
            });
        }
    };

