import React, { Component } from 'react';
import { Modal, Form, Input, message } from 'antd';
import PropTypes from 'prop-types';

const { TextArea } = Input;

class SubProjectModal extends Component {
    constructor(props) {
        super(props);
        this.state = {
            name: props.subProject ? props.subProject.name : '',
            description: props.subProject ? props.subProject.description : '',
            saving: false,
            nameError: '',
        };
    }

    componentDidUpdate(prevProps) {
        if (prevProps.visible !== this.props.visible && this.props.visible) {
            // Reset form when modal opens
            this.setState({
                name: this.props.subProject ? this.props.subProject.name : '',
                description: this.props.subProject ? this.props.subProject.description : '',
                saving: false,
                nameError: '',
            });
        }
    }

    handleNameChange = (e) => {
        const name = e.target.value;
        this.setState({ name, nameError: '' });
    };

    handleDescriptionChange = (e) => {
        this.setState({ description: e.target.value });
    };

    validate = () => {
        const { name } = this.state;
        const { existingNames, subProject } = this.props;

        if (!name || !name.trim()) {
            this.setState({ nameError: 'Sub-project name is required' });
            return false;
        }

        if (name.trim().length < 2) {
            this.setState({ nameError: 'Name must be at least 2 characters' });
            return false;
        }

        // Check for duplicates (exclude current sub-project when editing)
        const isDuplicate = existingNames.some(
            (existing) =>
                existing.toLowerCase() === name.trim().toLowerCase() &&
                (!subProject || existing.toLowerCase() !== subProject.name.toLowerCase())
        );

        if (isDuplicate) {
            this.setState({ nameError: 'A sub-project with this name already exists' });
            return false;
        }

        return true;
    };

    handleOk = async () => {
        if (!this.validate()) return;

        const { name, description } = this.state;
        const { onSave } = this.props;

        this.setState({ saving: true });

        try {
            await onSave({ name: name.trim(), description: description.trim() });
        } catch (error) {
            message.error(error.message || 'Failed to save sub-project');
        } finally {
            this.setState({ saving: false });
        }
    };

    render() {
        const { visible, onCancel, subProject, projectName } = this.props;
        const { name, description, saving, nameError } = this.state;

        const isEdit = !!subProject;
        const title = isEdit
            ? `Edit Sub-Project: ${subProject.name}`
            : `Create Sub-Project in "${projectName}"`;

        return (
            <Modal
                title={title}
                visible={visible}
                onOk={this.handleOk}
                onCancel={onCancel}
                confirmLoading={saving}
                okText={isEdit ? 'Save Changes' : 'Create Sub-Project'}
                cancelText="Cancel"
                destroyOnClose
                width={500}
            >
                <Form layout="vertical">
                    <Form.Item
                        label="Sub-Project Name"
                        required
                        validateStatus={nameError ? 'error' : ''}
                        help={nameError}
                    >
                        <Input
                            placeholder="e.g., Training in May, Community Engagement"
                            value={name}
                            onChange={this.handleNameChange}
                            maxLength={100}
                            autoFocus
                            onPressEnter={this.handleOk}
                        />
                    </Form.Item>
                    <Form.Item label="Description (Optional)">
                        <TextArea
                            placeholder="Brief description of this sub-project"
                            value={description}
                            onChange={this.handleDescriptionChange}
                            rows={3}
                            maxLength={500}
                        />
                    </Form.Item>
                </Form>
            </Modal>
        );
    }
}

SubProjectModal.propTypes = {
    visible: PropTypes.bool.isRequired,
    onCancel: PropTypes.func.isRequired,
    onSave: PropTypes.func.isRequired,
    projectName: PropTypes.string,
    subProject: PropTypes.object,
    existingNames: PropTypes.array,
};

SubProjectModal.defaultProps = {
    projectName: '',
    subProject: null,
    existingNames: [],
};

export default SubProjectModal;



