/**
 * Sub-Project Service
 *
 * Manages CRUD operations for sub-projects using the DHIS2 dataStore API.
 * Sub-projects are stored under the namespace "sims-subprojects" with each
 * key being a program (project) ID and the value being an array of sub-project objects.
 *
 * Sub-project schema:
 * {
 *   id: string (UUID),
 *   name: string,
 *   description: string,
 *   createdAt: string (ISO 8601),
 *   createdBy: string (username)
 * }
 */
import { getInstance } from 'd2/lib/d2';

const NAMESPACE = 'sims-subprojects';

// Data Element that tags events with their sub-project
export const SUB_PROJECT_DE_NAME = '_SIMS_Sub_Project';
export const SUB_PROJECT_DE_CODE = 'SIMS_SUB_PROJECT';

/**
 * Generate a UUID v4
 */
const generateId = () => {
    return 'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g, (c) => {
        const r = (Math.random() * 16) | 0;
        const v = c === 'x' ? r : (r & 0x3) | 0x8;
        return v.toString(16);
    });
};

/**
 * Ensure the dataStore namespace exists
 */
const ensureNamespace = async (api) => {
    try {
        await api.get(`dataStore/${NAMESPACE}`);
    } catch (error) {
        if (error.httpStatusCode === 404 || (error.message && error.message.includes('404'))) {
            // Namespace doesn't exist — it will be auto-created on first key post
            // No action needed here
        }
    }
};

/**
 * Get all sub-projects for a given program (project) ID
 * @param {string} programId - The DHIS2 program ID
 * @returns {Array} Array of sub-project objects
 */
export const getSubProjects = async (programId) => {
    try {
        const d2 = await getInstance();
        const api = d2.Api.getApi();
        const data = await api.get(`dataStore/${NAMESPACE}/${programId}`);
        return Array.isArray(data) ? data : [];
    } catch (error) {
        if (error.httpStatusCode === 404 || (error.message && error.message.includes('404'))) {
            return [];
        }
        console.error('Error fetching sub-projects:', error);
        throw error;
    }
};

/**
 * Create a new sub-project for a program
 * @param {string} programId - The DHIS2 program ID
 * @param {Object} subProject - Sub-project data { name, description }
 * @param {string} username - The creating user's username
 * @returns {Object} The created sub-project with generated id and timestamps
 */
export const createSubProject = async (programId, subProject, username) => {
    const d2 = await getInstance();
    const api = d2.Api.getApi();

    await ensureNamespace(api);

    const newSubProject = {
        id: generateId(),
        name: subProject.name.trim(),
        description: (subProject.description || '').trim(),
        createdAt: new Date().toISOString(),
        createdBy: username || 'unknown',
    };

    let existing = [];
    let keyExists = false;

    try {
        existing = await api.get(`dataStore/${NAMESPACE}/${programId}`);
        if (!Array.isArray(existing)) existing = [];
        keyExists = true;
    } catch (error) {
        if (error.httpStatusCode === 404 || (error.message && error.message.includes('404'))) {
            keyExists = false;
        } else {
            throw error;
        }
    }

    // Check for duplicate names
    const duplicate = existing.find(
        (sp) => sp.name.toLowerCase() === newSubProject.name.toLowerCase()
    );
    if (duplicate) {
        throw new Error(`A sub-project named "${newSubProject.name}" already exists in this project.`);
    }

    existing.push(newSubProject);

    if (keyExists) {
        await api.update(`dataStore/${NAMESPACE}/${programId}`, existing);
    } else {
        await api.post(`dataStore/${NAMESPACE}/${programId}`, existing);
    }

    return newSubProject;
};

/**
 * Update an existing sub-project
 * @param {string} programId - The DHIS2 program ID
 * @param {string} subProjectId - The sub-project UUID to update
 * @param {Object} updates - Fields to update { name, description }
 * @returns {Object} The updated sub-project
 */
export const updateSubProject = async (programId, subProjectId, updates) => {
    const d2 = await getInstance();
    const api = d2.Api.getApi();

    let existing;
    try {
        existing = await api.get(`dataStore/${NAMESPACE}/${programId}`);
        if (!Array.isArray(existing)) existing = [];
    } catch (error) {
        throw new Error('Sub-projects not found for this program.');
    }

    const index = existing.findIndex((sp) => sp.id === subProjectId);
    if (index === -1) {
        throw new Error('Sub-project not found.');
    }

    // Check for duplicate names (excluding the current sub-project)
    if (updates.name) {
        const duplicate = existing.find(
            (sp) => sp.id !== subProjectId && sp.name.toLowerCase() === updates.name.trim().toLowerCase()
        );
        if (duplicate) {
            throw new Error(`A sub-project named "${updates.name}" already exists in this project.`);
        }
    }

    existing[index] = {
        ...existing[index],
        ...(updates.name && { name: updates.name.trim() }),
        ...(updates.description !== undefined && { description: (updates.description || '').trim() }),
        updatedAt: new Date().toISOString(),
    };

    await api.update(`dataStore/${NAMESPACE}/${programId}`, existing);
    return existing[index];
};

/**
 * Delete a sub-project
 * @param {string} programId - The DHIS2 program ID
 * @param {string} subProjectId - The sub-project UUID to delete
 * @returns {boolean} True if successfully deleted
 */
export const deleteSubProject = async (programId, subProjectId) => {
    const d2 = await getInstance();
    const api = d2.Api.getApi();

    let existing;
    try {
        existing = await api.get(`dataStore/${NAMESPACE}/${programId}`);
        if (!Array.isArray(existing)) existing = [];
    } catch (error) {
        throw new Error('Sub-projects not found for this program.');
    }

    const filtered = existing.filter((sp) => sp.id !== subProjectId);
    if (filtered.length === existing.length) {
        throw new Error('Sub-project not found.');
    }

    if (filtered.length === 0) {
        // Remove the key entirely if no sub-projects remain
        await api.delete(`dataStore/${NAMESPACE}/${programId}`);
    } else {
        await api.update(`dataStore/${NAMESPACE}/${programId}`, filtered);
    }

    return true;
};

/**
 * Get or create the system data element used to tag events with sub-project IDs.
 * This data element (_SIMS_Sub_Project) stores the sub-project UUID on each event.
 * @returns {string} The data element ID
 */
export const getOrCreateSubProjectDataElement = async () => {
    const d2 = await getInstance();
    const api = d2.Api.getApi();

    // First, try to find existing data element by code
    try {
        const response = await api.get('dataElements', {
            filter: `code:eq:${SUB_PROJECT_DE_CODE}`,
            fields: 'id,name,code',
            paging: false,
        });

        if (response.dataElements && response.dataElements.length > 0) {
            return response.dataElements[0].id;
        }
    } catch (error) {
        console.warn('Error searching for sub-project data element:', error);
    }

    // Not found — create it
    const catComboResp = await api.get('categoryCombos', {
        filter: 'name:eq:default',
        fields: 'id',
        paging: false,
    });
    const defaultCatComboId = catComboResp.categoryCombos[0] && catComboResp.categoryCombos[0].id;

    const newDe = {
        name: SUB_PROJECT_DE_NAME,
        shortName: 'Sub-Project Tag',
        code: SUB_PROJECT_DE_CODE,
        description: 'System field that stores the sub-project ID for grouping events within a project.',
        domainType: 'TRACKER',
        valueType: 'TEXT',
        aggregationType: 'NONE',
        categoryCombo: { id: defaultCatComboId },
    };

    const createResp = await api.post('dataElements', newDe);
    const createdId = (createResp && createResp.response && createResp.response.uid) || (createResp && createResp.uid);

    if (!createdId) {
        throw new Error('Failed to create the _SIMS_Sub_Project data element.');
    }

    return createdId;
};

/**
 * Ensure the sub-project data element is linked to a program's first program stage.
 * @param {string} programId - The DHIS2 program ID
 * @returns {string} The data element ID that was linked
 */
export const ensureSubProjectDeLinked = async (programId) => {
    const d2 = await getInstance();
    const api = d2.Api.getApi();

    const deId = await getOrCreateSubProjectDataElement();

    // Fetch the program to get its first program stage
    const programResp = await api.get(`programs/${programId}`, {
        fields: 'id,programStages[id,programStageDataElements[dataElement[id]]]',
    });

    const programStage = programResp.programStages && programResp.programStages[0];
    if (!programStage) {
        throw new Error('Program has no program stages.');
    }

    // Check if already linked
    const existingDEs = programStage.programStageDataElements || [];
    const alreadyLinked = existingDEs.some((psde) => psde.dataElement && psde.dataElement.id === deId);

    if (!alreadyLinked) {
        // Fetch full program stage data to update
        const psData = await api.get(`programStages/${programStage.id}`, {
            fields: ':all,programStageSections[id,name,dataElements[id]]',
        });

        const updatedPSDEs = [...(psData.programStageDataElements || [])];
        updatedPSDEs.push({
            dataElement: { id: deId },
            compulsory: false,
            displayInReports: false,
        });
        psData.programStageDataElements = updatedPSDEs;

        await api.update(`programStages/${programStage.id}`, psData);
    }

    return deId;
};

export default {
    getSubProjects,
    createSubProject,
    updateSubProject,
    deleteSubProject,
    getOrCreateSubProjectDataElement,
    ensureSubProjectDeLinked,
    NAMESPACE,
    SUB_PROJECT_DE_NAME,
    SUB_PROJECT_DE_CODE,
};



